var documenterSearchIndex = {"docs":
[{"category":"section","location":"guide/#User-Guide","page":"User Guide","text":"This guide is automatically generated from the comprehensive USER_GUIDE.md.\n\nFor the most up-to-date information, see USER_GUIDE.md in the repository.\n\n\n\nPages = [\"guide.md\"]\nDepth = 3\n\n","title":"User Guide"},{"category":"section","location":"guide/#Quick-Start","page":"User Guide","text":"using MissingDataViz\nusing DataFrames\n\n# Create sample data with missing values\ndf = DataFrame(\n    Name = [\"Alice\", \"Bob\", missing, \"David\", \"Eve\"],\n    Age = [25, missing, 30, missing, 35],\n    Salary = [50000, 60000, missing, 70000, missing],\n    Department = [\"HR\", \"IT\", \"IT\", missing, \"HR\"]\n)\n\n# One-line complete analysis\nresults = diagnose_missing(df)\n# → Displays 4 plots automatically\n# → Returns statistics and figures\n\n","title":"Quick Start"},{"category":"section","location":"guide/#Core-Functions","page":"User Guide","text":"","title":"Core Functions"},{"category":"section","location":"guide/#Pattern-Detection","page":"User Guide","text":"# Get missing data pattern matrix (boolean)\npattern = missing_pattern(df)\n\n# Get percentage of missing values per column\npercentages = missing_percentage(df)\n\n# Get count of missing values per column\ncounts = missing_count(df)","title":"Pattern Detection"},{"category":"section","location":"guide/#Visualizations","page":"User Guide","text":"# Missing data matrix heatmap\nfig1 = plot_missing_matrix(df)\n\n# Bar chart of missing percentages\nfig2 = plot_missing_bars(df)\n\n# Correlation matrix of missingness\nfig3 = plot_missing_correlation(df)\n\n# Combined overview dashboard\nfig4 = plot_missing_overview(df)","title":"Visualizations"},{"category":"section","location":"guide/#All-in-One-Analysis","page":"User Guide","text":"# Interactive mode (default)\nresults = diagnose_missing(df)\n\n# Batch mode (generate HTML report)\nresults = diagnose_missing(df, report=true, output=\"report.html\")\n\n","title":"All-in-One Analysis"},{"category":"section","location":"guide/#Workflows","page":"User Guide","text":"","title":"Workflows"},{"category":"section","location":"guide/#Interactive-Analysis","page":"User Guide","text":"using MissingDataViz, DataFrames\n\ndf = # your data loading\n\n# Automatic analysis with plot display\nresults = diagnose_missing(df)\n\n# Access statistics\nprintln(\"Total missing: \", results[:stats][:total_missing])\nprintln(\"Overall percentage: \", results[:stats][:overall_percentage], \"%\")\n\n# Access per-column statistics\nfor (col, stats) in results[:stats][:columns]\n    println(\"$col: $(stats[:percentage])% missing\")\nend","title":"Interactive Analysis"},{"category":"section","location":"guide/#Batch-Reporting","page":"User Guide","text":"# Generate standalone HTML report\nresults = diagnose_missing(df, report=true, output=\"analysis.html\")\n\nprintln(\"Report saved to: \", results[:report_path])\n# → Report saved to: /absolute/path/to/analysis.html\n\n","title":"Batch Reporting"},{"category":"section","location":"guide/#Exporting-Plots","page":"User Guide","text":"All plotting functions return Makie.Figure objects. Export them using CairoMakie.save().\n\nusing CairoMakie\n\n# Generate a plot\nfig = plot_missing_matrix(df)\n\n# PNG (default 300 DPI)\nsave(\"output.png\", fig)\n\n# PDF (vector format, high quality)\nsave(\"output.pdf\", fig)\n\n# SVG (vector format, editable)\nsave(\"output.svg\", fig)\n\n# High-resolution PNG for publications\nsave(\"high_res.png\", fig, px_per_unit=3)  # 900 DPI equivalent\n\n","title":"Exporting Plots"},{"category":"section","location":"guide/#Troubleshooting","page":"User Guide","text":"","title":"Troubleshooting"},{"category":"section","location":"guide/#Plots-not-displaying-in-REPL","page":"User Guide","text":"Solution: Activate the CairoMakie backend explicitly\n\nusing CairoMakie\nCairoMakie.activate!()\n\nresults = diagnose_missing(df)","title":"Plots not displaying in REPL"},{"category":"section","location":"guide/#\"Directory-does-not-exist\"-error","page":"User Guide","text":"Solution: Create the output directory before generating reports\n\noutput_dir = \"reports\"\n!isdir(output_dir) && mkdir(output_dir)\n\nresults = diagnose_missing(df, report=true, output=\"reports/analysis.html\")","title":"\"Directory does not exist\" error"},{"category":"section","location":"guide/#Out-of-memory-with-large-datasets","page":"User Guide","text":"Solution: Use display=false to skip plot rendering\n\n# For very large datasets (>100K rows)\nresults = diagnose_missing(df, display=false)\n\n# Access statistics only\nprintln(results[:stats])\n\n","title":"Out of memory with large datasets"},{"category":"section","location":"guide/#Performance-Tips","page":"User Guide","text":"","title":"Performance Tips"},{"category":"section","location":"guide/#For-Large-Datasets-(10K-rows)","page":"User Guide","text":"# Skip interactive display\nresults = diagnose_missing(df, display=false)\n\n# Generate report directly\nresults = diagnose_missing(df, \"report.html\", verbose=true)\n\n","title":"For Large Datasets (>10K rows)"},{"category":"section","location":"guide/#Complete-Reference","page":"User Guide","text":"For the full user guide with all examples, workflows, and advanced usage, see:\n\nUSER_GUIDE.md","title":"Complete Reference"},{"category":"section","location":"api/#API-Reference","page":"API Reference","text":"This page provides detailed documentation for all public functions in MissingDataViz.jl.\n\n","title":"API Reference"},{"category":"section","location":"api/#Pattern-Detection","page":"API Reference","text":"Functions for detecting and analyzing missing data patterns.\n\n","title":"Pattern Detection"},{"category":"section","location":"api/#Visualizations","page":"API Reference","text":"","title":"Visualizations"},{"category":"section","location":"api/#Matrix-Heatmap","page":"API Reference","text":"","title":"Matrix Heatmap"},{"category":"section","location":"api/#Bar-Charts","page":"API Reference","text":"","title":"Bar Charts"},{"category":"section","location":"api/#Correlation-Matrix","page":"API Reference","text":"","title":"Correlation Matrix"},{"category":"section","location":"api/#Overview-Dashboard","page":"API Reference","text":"","title":"Overview Dashboard"},{"category":"section","location":"api/#MCAR-Diagnostic-Dashboard","page":"API Reference","text":"","title":"MCAR Diagnostic Dashboard"},{"category":"section","location":"api/#MCAR-Statistical-Tests","page":"API Reference","text":"Functions to test the MCAR (Missing Completely At Random) assumption. Each test returns a TestResult; compare_mcar_tests runs all three and produces a consensus.","title":"MCAR Statistical Tests"},{"category":"section","location":"api/#Interpretation-Helpers","page":"API Reference","text":"Human-readable interpretation of individual test results.","title":"Interpretation Helpers"},{"category":"section","location":"api/#Result-Types","page":"API Reference","text":"","title":"Result Types"},{"category":"section","location":"api/#Synthetic-Data-Generators","page":"API Reference","text":"Generators with known ground truth, used to validate the MCAR tests and to demonstrate expected behavior under each missingness mechanism.\n\n","title":"Synthetic Data Generators"},{"category":"section","location":"api/#Reports-and-Workflows","page":"API Reference","text":"Functions for generating reports and complete workflows.\n\n","title":"Reports and Workflows"},{"category":"section","location":"api/#Data-Structures","page":"API Reference","text":"","title":"Data Structures"},{"category":"section","location":"api/#Error-Types","page":"API Reference","text":"Custom exceptions raised on invalid input or insufficient data.\n\n","title":"Error Types"},{"category":"section","location":"api/#Utility-Functions","page":"API Reference","text":"","title":"Utility Functions"},{"category":"section","location":"api/#Index","page":"API Reference","text":"","title":"Index"},{"category":"function","location":"api/#MissingDataViz.missing_pattern","page":"API Reference","text":"missing_pattern(df::DataFrame) → BitMatrix\n\nConverts a DataFrame to a binary matrix (true = missing, false = present). OPTIMIZED: Uses Julia's efficient broadcast for minimal allocations.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nBitMatrix: Binary matrix with same dimensions as df (true = missing, false = present)\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, missing])\npattern = missing_pattern(df)\n# 3×2 BitMatrix:\n#  0  0\n#  1  0\n#  0  1\n\n\n\n\n\n","title":"MissingDataViz.missing_pattern"},{"category":"function","location":"api/#MissingDataViz.missing_count","page":"API Reference","text":"missing_count(df::DataFrame) → Vector{Int}\n\nCounts the absolute number of missing values per column.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Int}: Number of missing values for each column\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[missing, missing, 6])\ncounts = missing_count(df)  # [1, 2]\n\n\n\n\n\n","title":"MissingDataViz.missing_count"},{"category":"function","location":"api/#MissingDataViz.missing_percentage","page":"API Reference","text":"missing_percentage(df::DataFrame) → Vector{Float64}\n\nCalculates the percentage of missing values per column.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Float64}: Percentages (0.0 to 100.0) for each column\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, 6])\npct = missing_percentage(df)  # [33.33, 0.0]\n\n\n\n\n\n","title":"MissingDataViz.missing_percentage"},{"category":"function","location":"api/#MissingDataViz.pattern_counts","page":"API Reference","text":"pattern_counts(df::DataFrame) → Dict{Vector{Bool}, Int}\n\nIdentifies unique missing data patterns and counts their occurrences. OPTIMIZED: Uses views, pre-allocation, and get() for better performance.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nDict{Vector{Bool}, Int}: Dictionary mapping each unique pattern to its count\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3, missing], B=[missing, 2, missing, 2])\ncounts = pattern_counts(df)\n# Dict with patterns as keys, counts as values\n\n\n\n\n\n","title":"MissingDataViz.pattern_counts"},{"category":"function","location":"api/#MissingDataViz.pattern_counts_parallel","page":"API Reference","text":"pattern_counts_parallel(df::DataFrame) → Dict{Vector{Bool}, Int}\n\nParallel version of pattern_counts for large datasets (>10k rows). Uses multi-threading for significant performance gains on multi-core systems.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nDict{Vector{Bool}, Int}: Dictionary mapping each unique pattern to its count\n\nPerformance\n\nRecommended for datasets >10k rows with ≥4 CPU cores\nFalls back to sequential version for small datasets (overhead > benefit)\n\n\n\n\n\n","title":"MissingDataViz.pattern_counts_parallel"},{"category":"function","location":"api/#MissingDataViz.pattern_frequency","page":"API Reference","text":"pattern_frequency(df::DataFrame) → Vector{Tuple{Vector{Bool}, Int}}\n\nReturns unique patterns sorted by frequency (most common first).\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Tuple{Vector{Bool}, Int}}: Vector of (pattern, count) tuples sorted by count descending\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[missing, 2, missing])\nfreq = pattern_frequency(df)\n# [(pattern1, count1), (pattern2, count2), ...] sorted by count\n\n\n\n\n\n","title":"MissingDataViz.pattern_frequency"},{"category":"function","location":"api/#MissingDataViz.row_missing_stats","page":"API Reference","text":"row_missing_stats(df::DataFrame) → Vector{Float64}\n\nCalculates the percentage of missing values for each row. OPTIMIZED: Pre-allocation and single-pass calculation.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Float64}: Percentage of missing values per row (0.0 to 100.0)\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[missing, 2, missing])\nrow_stats = row_missing_stats(df)\n# [50.0, 50.0, 50.0]  (each row has 1 out of 2 missing)\n\n\n\n\n\n","title":"MissingDataViz.row_missing_stats"},{"category":"function","location":"api/#MissingDataViz.column_missing_distribution","page":"API Reference","text":"column_missing_distribution(df::DataFrame) → DataFrame\n\nCreates a detailed distribution table of missing values by column.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nDataFrame: Table with columns column_name, n_missing, pct_missing, n_present\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, 6])\ndist = column_missing_distribution(df)\n# 2×4 DataFrame with distribution stats\n\n\n\n\n\n","title":"MissingDataViz.column_missing_distribution"},{"category":"function","location":"api/#MissingDataViz.extreme_patterns","page":"API Reference","text":"extreme_patterns(df::DataFrame) → NamedTuple\n\nIdentifies extreme cases: rows/columns that are 100% missing or 100% complete.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nNamedTuple with fields:\nrows_all_missing::Vector{Int}: Row indices where all values are missing\nrows_all_complete::Vector{Int}: Row indices where no values are missing\ncols_all_missing::Vector{Int}: Column indices where all values are missing\ncols_all_complete::Vector{Int}: Column indices where no values are missing\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[missing, 1], B=[missing, missing])\nextremes = extreme_patterns(df)\n# extremes.rows_all_missing == [1]\n# extremes.cols_all_missing == [2]\n\n\n\n\n\n","title":"MissingDataViz.extreme_patterns"},{"category":"function","location":"api/#MissingDataViz.summarize_missing","page":"API Reference","text":"summarize_missing(df::DataFrame) → NamedTuple\n\nGenerates a comprehensive summary of missing data patterns and statistics.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nNamedTuple containing:\ntotal_cells::Int: Total number of cells in DataFrame\nn_missing::Int: Total number of missing values\npct_missing::Float64: Overall percentage of missing values\nby_column::DataFrame: Distribution statistics by column\nby_row::Vector{Float64}: Percentage missing per row\nextremes::NamedTuple: Extreme patterns (all missing/complete rows/cols)\ntop_patterns::Vector: Top 5 most frequent patterns\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, missing])\nsummary = summarize_missing(df)\nprintln(\"Total missing: \", summary.n_missing)\nprintln(\"By column: \", summary.by_column)\n\n\n\n\n\n","title":"MissingDataViz.summarize_missing"},{"category":"function","location":"api/#MissingDataViz.missing_correlation","page":"API Reference","text":"missing_correlation(df::DataFrame)\n\nCalculate the Pearson correlation matrix between missing data patterns across columns.\n\nThis function converts the DataFrame to a binary matrix (1 = missing, 0 = present) and computes pairwise correlations between columns. Positive correlations indicate columns that tend to have missing values together, while negative correlations suggest opposite patterns.\n\nArguments\n\ndf::DataFrame: Input DataFrame to analyze\n\nReturns\n\nMatrix{Float64}: Correlation matrix (ncols × ncols) where each entry (i,j)  represents the correlation between missingness patterns of columns i and j\n\nExamples\n\nusing DataFrames, MissingDataViz\n\ndf = DataFrame(\n    A = [1, missing, 3, missing, 5],\n    B = [missing, 2, 3, missing, 5],      # Correlates with A\n    C = [1, 2, missing, 4, missing]       # Different pattern\n)\n\ncorr_matrix = missing_correlation(df)\n# corr_matrix[1,2] will be high (A and B missing together)\n\nNotes\n\nReturns NaN for columns with no missing values (constant pattern, no variance)\nDiagonal elements are always 1.0 (perfect self-correlation)\nCorrelation ranges from -1.0 (opposite patterns) to 1.0 (identical patterns)\n\n\n\n\n\n","title":"MissingDataViz.missing_correlation"},{"category":"function","location":"api/#MissingDataViz.plot_missing_matrix","page":"API Reference","text":"plot_missing_matrix(df::DataFrame; kwargs...)\n\nCreate a heatmap visualizing missing data patterns in a DataFrame with customization options.\n\nArguments\n\ndf::DataFrame: DataFrame to visualize\n\nKeyword Arguments\n\nfigsize::Tuple{Int,Int}: Figure dimensions in pixels. Default: (1000, 600)\ncolormap::Symbol: Color scheme for the heatmap. Default: :grays\nshow_sparkline::Bool: Display sparkline showing % missing per row. Default: true\nmax_rows_display::Int: Maximum number of rows to display. Use -1 for no limit. Default: 5000\nlabels::NamedTuple: Custom labels for plot elements. Default labels in English.\nxlabel: X-axis label (default: \"Variables\")\nylabel: Y-axis label (default: \"Observations\")\ntitle: Plot title (default: \"Missing Data Pattern\")\ncolorbar_label: Colorbar label (default: \"Data Status\")\ncolorbar_present: Label for present values (default: \"Present\")\ncolorbar_missing: Label for missing values (default: \"Missing\")\nsparkline_ylabel: Sparkline Y-axis label (default: \"% Missing\")\n\nReturns\n\nFigure: Makie Figure object containing the heatmap\n\nExamples\n\nusing MissingDataViz\nusing DataFrames\n\ndf = DataFrame(\n    A = [1, missing, 3, 4, missing],\n    B = [missing, 2, 3, missing, 5],\n    C = [1, 2, 3, 4, 5]\n)\n\n# Basic usage\nfig = plot_missing_matrix(df)\n\n# French labels\nfig = plot_missing_matrix(df; labels=(\n    xlabel = \"Variables\",\n    ylabel = \"Observations\",\n    title = \"Motif de Données Manquantes\",\n    colorbar_label = \"Statut\",\n    colorbar_present = \"Présent\",\n    colorbar_missing = \"Manquant\",\n    sparkline_ylabel = \"% Manquant\"\n))\n\n# Medical context\nfig = plot_missing_matrix(df; labels=(\n    xlabel = \"Clinical Variables\",\n    ylabel = \"Patients\",\n    title = \"Missing Data in Patient Records\"\n))\n\n# Custom size without sparkline\nfig = plot_missing_matrix(df; figsize=(800, 600), show_sparkline=false)\n\n# Colorblind-friendly colormap\nfig = plot_missing_matrix(df; colormap=:viridis)\n\n# Display more rows\nfig = plot_missing_matrix(df; max_rows_display=10000)\n\n# Combined customization\nfig = plot_missing_matrix(df; \n    figsize=(1200, 800), \n    colormap=:thermal,\n    show_sparkline=true,\n    max_rows_display=3000,\n    labels=(xlabel=\"Features\", ylabel=\"Samples\")\n)\n\nNotes\n\nBlack = missing value (with default :grays colormap)\nWhite = present value (with default :grays colormap)\nFor datasets >50 columns, only the first 50 columns are displayed\nAvailable colormaps: :grays, :viridis, :plasma, :thermal, :RdBu, etc.\nPartial label override is supported (only specify labels you want to change)\n\n\n\n\n\n","title":"MissingDataViz.plot_missing_matrix"},{"category":"function","location":"api/#MissingDataViz.plot_missing_bars","page":"API Reference","text":"plot_missing_bars(df::DataFrame; sort::Bool=true, figsize::Tuple{Int,Int}=(800, 600), \n                  threshold::Union{Nothing,Float64}=nothing, orientation::Symbol=:auto)\n\nCreate a bar chart showing the percentage of missing values for each column.\n\nArguments\n\ndf::DataFrame: Input DataFrame to analyze\nsort::Bool=true: Sort columns by missing percentage (descending)\nfigsize::Tuple{Int,Int}=(800, 600): Figure dimensions (width, height)\nthreshold::Union{Nothing,Float64}=nothing: Display horizontal threshold line at specified percentage (0-100)\norientation::Symbol=:auto: Bar orientation (:vertical, :horizontal, or :auto which uses horizontal if >20 columns)\n\nReturns\n\nFigure: Makie Figure object containing the bar chart\n\nExamples\n\nusing DataFrames, MissingDataViz\n\ndf = DataFrame(\n    A = [1, missing, 3, missing, 5],\n    B = [missing, missing, missing, 4, 5],\n    C = [1, 2, 3, 4, 5]\n)\n\n# Basic bar chart\nfig = plot_missing_bars(df)\n\n# With custom threshold line at 30%\nfig = plot_missing_bars(df, threshold=30.0)\n\n# Horizontal bars for many columns\nfig = plot_missing_bars(df, orientation=:horizontal)\n\nColor coding\n\nBlue: < 20% missing\nOrange: 20-50% missing\nRed: >= 50% missing\n\nNotes\n\nVertical orientation (default for ≤20 columns): No label overlap issues\nHorizontal orientation (automatic for >20 columns): If column labels overlap,  increase figure height: figsize=(800, 1200) or use figsize=(1000, 50*n_cols)\nFor very wide datasets (>50 columns), consider filtering to most relevant columns first\n\n\n\n\n\n","title":"MissingDataViz.plot_missing_bars"},{"category":"function","location":"api/#MissingDataViz.plot_missing_correlation","page":"API Reference","text":"plot_missing_correlation(df::DataFrame; figsize::Tuple{Int,Int}=(800, 800), \n                         show_values::Bool=:auto)\n\nCreate a heatmap visualization of the missing data pattern correlation matrix.\n\nArguments\n\ndf::DataFrame: Input DataFrame to analyze\nfigsize::Tuple{Int,Int}=(800, 800): Figure dimensions (width, height)\nshow_values::Bool=:auto: Display correlation values in cells. Auto shows values if ≤10 columns\n\nReturns\n\nFigure: Makie Figure object containing the correlation heatmap\n\nExamples\n\nusing DataFrames, MissingDataViz\n\ndf = DataFrame(\n    A = [1, missing, 3, missing, 5],\n    B = [missing, 2, 3, missing, 5],\n    C = [1, 2, missing, 4, missing]\n)\n\nfig = plot_missing_correlation(df)\nfig = plot_missing_correlation(df, show_values=true)  # Force display values\n\nInterpretation\n\nRed (positive correlation): Columns tend to have missing values together\nBlue (negative correlation): When one column is missing, the other tends to be present\nWhite (zero correlation): No relationship between missing patterns\nDiagonal = 1.0: Each column perfectly correlates with itself\n\n\n\n\n\n","title":"MissingDataViz.plot_missing_correlation"},{"category":"function","location":"api/#MissingDataViz.plot_missing_overview","page":"API Reference","text":"plot_missing_overview(df::DataFrame; \n                      figsize::Tuple{Int,Int}=(1800, 600),\n                      layout::Symbol=:horizontal,\n                      threshold::Union{Nothing,Float64}=nothing,\n                      show_correlation_values::Union{Bool,Symbol}=:auto)\n\nCreate a comprehensive overview dashboard combining all three missing data visualizations.\n\nCombines:\n\nMissing data matrix (left/top): Shows where missing values occur row-by-row\nBar chart (center): Shows percentage of missing values per column\nCorrelation matrix (right/bottom): Shows relationships between missing patterns\n\nArguments\n\ndf::DataFrame: Input DataFrame to analyze\nfigsize::Tuple{Int,Int}=(1800, 600): Figure dimensions (width, height)\nlayout::Symbol=:horizontal: Layout (:horizontal = 1×3 grid, :vertical = 3×1 grid)\nthreshold::Union{Nothing,Float64}=nothing: Optional threshold line for bar chart\nshow_correlation_values::Union{Bool,Symbol}=:auto: Show values in correlation heatmap\n\nReturns\n\nFigure: Makie Figure containing all three plots in unified layout\n\nExamples\n\nusing DataFrames, MissingDataViz\n\ndf = DataFrame(\n    A = [1, missing, 3, missing, 5],\n    B = [missing, missing, missing, 4, 5],\n    C = [1, 2, 3, 4, 5]\n)\n\n# Default horizontal layout\nfig = plot_missing_overview(df)\n\n# Vertical layout\nfig = plot_missing_overview(df, layout=:vertical, figsize=(1000, 1800))\n\n# With threshold line on bar chart\nfig = plot_missing_overview(df, threshold=30.0)\n\nUse Cases\n\nQuick audit: Complete picture of missing data in single view\nExecutive reports: Comprehensive visual for presentations\nExploratory analysis: Identify patterns, severity, and correlations simultaneously\nBefore imputation: Understand data structure before choosing imputation strategy\n\n\n\n\n\n","title":"MissingDataViz.plot_missing_overview"},{"category":"function","location":"api/#MissingDataViz.plot_missing_diagnosis","page":"API Reference","text":"plot_missing_diagnosis(df; alpha=0.05, figsize=(1400, 900), title=\"Missing Data Diagnosis\")\n\nGenerate a 2×2 integrated dashboard combining all missing data visualizations and MCAR statistical tests.\n\nLayout\n\nTop-left:     Missing data matrix (heatmap)\nTop-right:    Missing percentage bar chart\nBottom-left:  Missing correlation heatmap\nBottom-right: MCAR test results (p-value bar chart)\n\nArguments\n\ndf::DataFrame: Input DataFrame (may contain missing values)\nalpha::Float64=0.05: Significance threshold for MCAR tests\nfigsize::Tuple=(1400, 900): Figure dimensions in pixels\ntitle::String: Dashboard title\n\nReturns\n\nFigure: Makie figure object containing all 4 panels\n\nNotes\n\nRuns compare_mcar_tests() internally — may take a few seconds on large datasets\nColumns with no missing values are excluded from MCAR tests automatically\nAnnotations highlight columns where MCAR is rejected\n\nExamples\n\nusing MissingDataViz, DataFrames, Random\nRandom.seed!(42)\ndf = generate_mar_data(300, 5, 0.20)\nfig = plot_missing_diagnosis(df)\nsave(\"diagnosis_dashboard.png\", fig)\n\n\n\n\n\n","title":"MissingDataViz.plot_missing_diagnosis"},{"category":"function","location":"api/#MissingDataViz.plot_mcar_test_results","page":"API Reference","text":"plot_mcar_test_results(results; alpha=0.05, figsize=(800, 500), title=\"MCAR Test Results\")\n\nCreate a horizontal bar plot visualizing p-values from MCAR tests.\n\nArguments\n\nresults: Either a MCARTestComparison (from compare_mcar_tests()) or a Vector{TestResult}\nalpha::Float64=0.05: Significance threshold (shown as vertical line)\nfigsize::Tuple=(800, 500): Figure dimensions in pixels\ntitle::String=\"MCAR Test Results\": Plot title\n\nReturns\n\nFigure: Makie figure object\n\nColor coding\n\n🟢 Green (MCAR_NOT_REJECTED): No evidence against MCAR\n🔴 Red (MCAR_REJECTED): Significant evidence against MCAR\n⚫ Gray (INCONCLUSIVE): Insufficient data to conclude\n\nNotes\n\nP-values are displayed on a -log10 scale for readability\nThe vertical dashed line marks -log10(alpha), the decision threshold\nBars exceeding the threshold line indicate MCAR violations\n\nExamples\n\nusing MissingDataViz, DataFrames, Random\nRandom.seed!(42)\ndf = generate_mar_data(200, 4, 0.20)\ncomparison = compare_mcar_tests(df)\nfig = plot_mcar_test_results(comparison)\nsave(\"mcar_results.png\", fig)\n\n\n\n\n\n","title":"MissingDataViz.plot_mcar_test_results"},{"category":"function","location":"api/#MissingDataViz.MCARTests.test_mcar_little","page":"API Reference","text":"test_mcar_little(df; alpha=0.05, max_patterns=50) -> TestResult\n\nPerform Little's MCAR test (1988) - a global test for MCAR assumption.\n\nTests whether missing data patterns are independent of data values across ALL variables simultaneously.\n\nArguments\n\ndf::DataFrame: Input dataset (numeric columns recommended)\nalpha::Float64: Significance level (default: 0.05)\nmax_patterns::Int: Maximum unique patterns to process (default: 50)\n\nReturns\n\nTestResult with chi-square statistic, p-value, and MCAR decision.\n\nKey Limitation\n\n⚠️ LOW POWER for weak/localized MAR - Use with pairwise tests! Always validate with testmcarlogistic() or testmcarmeans().\n\nSee package documentation for detailed workflow examples.\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.test_mcar_little"},{"category":"function","location":"api/#MissingDataViz.MCARTests.test_mcar_means","page":"API Reference","text":"test_mcar_means(df, col_missing, col_complete; alpha=0.05) -> TestResult\n\nTest whether missingness in col_missing is associated with the mean of col_complete using Welch's t-test.\n\nSplits observations into:\n\nGroup 0: rows where col_missing is observed\nGroup 1: rows where col_missing is missing\n\nThen tests H0: mean(Group 0) = mean(Group 1).\n\nArguments\n\ndf::DataFrame: Input dataset.\ncol_missing::Symbol: Column whose missingness defines the groups.\ncol_complete::Symbol: Numeric column compared between groups.\nalpha::Float64: Significance level (default: 0.05).\n\nReturns\n\nA TestResult with:\n\ntest_name: \"MCAR Means Test (Welch t-test)\"\nstatistic: Welch t-statistic\npvalue: Two-sided p-value\ndegrees_of_freedom: Welch–Satterthwaite approximation\ndetails: group sizes, means, standard deviations\nwarnings: non-empty if assumptions may be violated\n\nRaises\n\nArgumentError if columns are missing from df\nArgumentError if col_complete contains missing values\nArgumentError if fewer than 3 observations in either group\n\nMathematical Details\n\nThe test splits observations into:\n\nGroup 0: col_missing is observed\nGroup 1: col_missing is missing\n\nWelch's t-statistic:     t = (mean₀ - mean₁) / √(s₀²/n₀ + s₁²/n₁)\n\nNull hypothesis H₀: mean₀ = mean₁ (MCAR holds)\n\nIf p < alpha → reject H₀ → col_complete predicts missingness → MCAR violated.\n\nInterpretation\n\np < 0.01: Strong evidence against MCAR. Investigate relationship.\np < 0.05: Moderate evidence. Use caution with simple imputation.\np ≥ 0.05: No evidence against MCAR for this pair.\n\nLimitations\n\nPairwise only (does not detect multivariate patterns)\nAssumes approximate normality for small samples (n < 30)\nOnly detects mean differences (not variance or distributional)\nRequires fully observed numeric predictor\n\nSee Also\n\nFull theoretical guide: docs/guides/mcar_means_guide.md\nBatch testing: test_all_mcar_means\nAlternative tests: test_mcar_logistic, test_mcar_little\n\nExample\n\ndf = generate_mar_data(200, 4, 0.20)\nresult = test_mcar_means(df, :x2, :x1)\nprintln(result)\n# MCAR rejected — x1 predicts missingness in x2\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.test_mcar_means"},{"category":"function","location":"api/#MissingDataViz.MCARTests.test_all_mcar_means","page":"API Reference","text":"test_all_mcar_means(df; alpha=0.05, correction=:bonferroni) -> Vector{TestResult}\n\nRun test_mcar_means for all valid pairs (colmissing, colcomplete) where colmissing has at least one missing value and colcomplete is fully observed and numeric.\n\nApplies multiple testing correction to control the family-wise error rate across all pairwise tests.\n\nArguments\n\ndf::DataFrame: Input dataset.\nalpha::Float64: Family-wise significance level (default: 0.05).\ncorrection::Symbol: Multiple testing correction method.\n:bonferroni — conservative, controls FWER (default)\n:none — no correction (use only for exploratory analysis)\n\nReturns\n\nVector{TestResult} sorted by p-value (ascending).\n\nNotes\n\nBonferroni correction divides alpha by the number of tests: alpha_adjusted = alpha / n_tests\n\nThis is conservative when tests are correlated (shared columns), but is the safest choice for confirmatory analysis.\n\nSee Also\n\nTheoretical guide: docs/guides/mcar_means_guide.md\nIndividual test: test_mcar_means\nResults summary: summary_table\n\nExample\n\ndf = generate_mar_data(200, 6, 0.20)\nresults = test_all_mcar_means(df)\nfor r in results\n    println(r)\nend\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.test_all_mcar_means"},{"category":"function","location":"api/#MissingDataViz.MCARTests.test_mcar_logistic","page":"API Reference","text":"test_mcar_logistic(df, col_missing; alpha=0.05, exclude_cols=Symbol[]) -> TestResult\n\nTest whether missingness in col_missing can be predicted by other columns using logistic regression.\n\nCreates a binary outcome y:\n\ny = 1 if col_missing is missing\ny = 0 if col_missing is observed\n\nThen fits: logit(P(y=1)) = β₀ + β₁x₁ + β₂x₂ + ...\n\nwhere x₁, x₂, ... are all other columns with ≥80% observed values. Rows where a predictor is missing are dropped (complete case analysis).\n\nThe MCAR decision comes from a global likelihood ratio test of H0: β₁ = β₂ = ... = βₖ = 0, comparing the fitted model against the intercept-only model. The LR statistic follows a chi-squared distribution with k degrees of freedom under H0, where k is the number of estimated predictor coefficients.\n\nArguments\n\ndf::DataFrame: Input dataset.\ncol_missing::Symbol: Column whose missingness is being tested.\nalpha::Float64: Significance level (default: 0.05).\nexclude_cols::Vector{Symbol}: Columns to exclude as predictors (default: empty).\n\nReturns\n\nA TestResult with:\n\ntest_name: \"MCAR Logistic Regression Test\"\nstatistic: Likelihood ratio statistic (null deviance − model deviance)\npvalue: Global p-value from the likelihood ratio test\ndegrees_of_freedom: Number of estimated predictor coefficients\ndetails: Coefficient table, significant predictors, model summary, and min_pvalue (reported for interpretation only)\nwarnings: Warnings for small samples, separation issues, dropped rows, etc.\n\nRaises\n\nArgumentError if col_missing is not in df\nArgumentError if df has fewer than 10 rows\n\nEdge cases (no missing values, all values missing, no usable predictors, model fitting failure) return an INCONCLUSIVE TestResult rather than throwing.\n\nInterpretation\n\nGlobal LR test p < alpha → MCAR rejected\nGlobal LR test p ≥ alpha → MCAR not rejected\n\nIndividual predictor p-values in details[\"significant_predictors\"] identify which variables are associated with missingness — useful for building an imputation model — but are not used to decide.\n\nExample\n\ndf = generate_mar_data(200, 5, 0.20)\nresult = test_mcar_logistic(df, :x2)\nprintln(result)\n# Check which variables predict missingness:\nfor pred in result.details[\"significant_predictors\"]\n    println(\"⚠️  $(pred[\"variable\"]) predicts missingness (p=$(pred[\"pvalue\"]))\")\nend\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.test_mcar_logistic"},{"category":"function","location":"api/#MissingDataViz.MCARTests.compare_mcar_tests","page":"API Reference","text":"compare_mcar_tests(df; alpha=0.05, verbose=true) -> MCARTestComparison\n\nRun and compare all three MCAR tests on a dataset.\n\nExecutes Little's test (global), pairwise t-tests, and logistic regression tests, then provides a comprehensive comparison and recommendation.\n\nArguments\n\ndf::DataFrame: Input dataset\nalpha::Float64: Significance level (default: 0.05)\nverbose::Bool: Print detailed comparison (default: true)\n\nReturns\n\nMCARTestComparison struct containing all test results and recommendations.\n\nExample\n\ncomparison = compare_mcar_tests(df)\n\n# Access individual results\ncomparison.little_result\ncomparison.logistic_results[:age]\ncomparison.means_results[:age]\n\n# View summary\nprintln(comparison.summary)\nprintln(comparison.recommendation)\n\nInterpretation Guide\n\nThe function identifies four scenarios:\n\nAgreement (all tests aligned)\nAll reject OR all accept MCAR\nRecommendation: Trust the consensus\nPartial disagreement\nLittle accepts, but some pairwise tests reject\nIndicates: Weak or localized MAR\nRecommendation: Use pairwise results (more sensitive)\nComplete disagreement\nMixed results across tests\nIndicates: Complex missing mechanism\nRecommendation: Use most conservative approach (assume MAR/MNAR)\nInsufficient data\nNo test (Little's or pairwise) reached a real decision\nThis is NOT evidence that MCAR holds — it means nothing could be computed (e.g. too few rows, no complete predictor column)\nRecommendation: Do not interpret as MCAR; fix the underlying data issue\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.compare_mcar_tests"},{"category":"function","location":"api/#MissingDataViz.MCARTests.summary_table","page":"API Reference","text":"summary_table(results::Vector{TestResult}) -> DataFrame\n\nConvert a vector of TestResult objects into a compact summary table suitable for quick inspection and export.\n\nArguments\n\nresults::Vector{TestResult}: Test results from test_all_mcar_means or similar.\n\nReturns\n\nA DataFrame with columns:\n\ncol_missing::String: Column being tested for missingness.\ncol_complete::String: Predictor column.\nstatistic::Float64: Test statistic.\npvalue::Float64: p-value.\ndecision::String: Test decision (MCARREJECTED / MCARNOT_REJECTED / INCONCLUSIVE).\nn_observed::Int: Number of observations where col_missing is observed.\nn_missing::Int: Number of observations where col_missing is missing.\nmean_diff::Float64: Difference in means between groups.\n\nNotes\n\nThis is a convenience function for display and export. The full TestResult objects contain additional metadata (warnings, degrees of freedom, etc.) that are not included in this summary table.\n\nExample\n\ndf = generate_mar_data(200, 6, 0.20)\nresults = test_all_mcar_means(df)\ntable = summary_table(results)\nprintln(table)\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.summary_table"},{"category":"function","location":"api/#MissingDataViz.MCARTests.interpret_mcar_little","page":"API Reference","text":"interpret_mcar_little(result::TestResult) -> String\n\nGenerate human-readable interpretation of Little's test results.\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.interpret_mcar_little"},{"category":"function","location":"api/#MissingDataViz.MCARTests.interpret_logistic_result","page":"API Reference","text":"interpret_logistic_result(result::TestResult) -> String\n\nGenerate a human-readable interpretation of logistic regression test results.\n\nReturns a formatted text summary including:\n\nOverall MCAR decision (from the global LR test) with MAR/MNAR distinction\nList of significant predictors with odds ratio interpretation\nRecommended imputation strategy\nSensitivity analysis guidance\nWarnings if applicable\n\nExample\n\nresult = test_mcar_logistic(df, :age)\ninterpretation = interpret_logistic_result(result)\nprintln(interpretation)\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.interpret_logistic_result"},{"category":"type","location":"api/#MissingDataViz.MCARTests.TestResult","page":"API Reference","text":"TestResult\n\nUnified result structure returned by all MCAR test functions.\n\nFields\n\ntest_name::String: Name of the statistical test performed.\nstatistic::Float64: Value of the test statistic (t, chi2, F, etc.).\npvalue::Float64: p-value of the test.\nalpha::Float64: Significance threshold used (default 0.05).\ndecision::MCARMechanism: Inferred mechanism based on pvalue vs alpha.\ndegrees_of_freedom::Union{Float64, Nothing}: Degrees of freedom if applicable.\ndetails::Dict{String, Any}: Additional test-specific information.\nwarnings::Vector{String}: Non-fatal warnings (small sample, non-normality, etc.).\n\nNotes\n\nA decision of MCAR_NOT_REJECTED does NOT confirm MCAR. It only indicates no significant dependence was detected among observed variables. Distinguishing MAR from MNAR requires domain knowledge and cannot be inferred from statistical tests alone.\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.TestResult"},{"category":"type","location":"api/#MissingDataViz.MCARTests.MCARMechanism","page":"API Reference","text":"MCARMechanism\n\nEnum representing the inferred missing data mechanism based on test results.\n\nMCAR_NOT_REJECTED: No significant evidence of MCAR violation detected.\nMCAR_REJECTED: Significant evidence that MCAR assumption is violated.\nINCONCLUSIVE: Test could not reach a conclusion (insufficient data, etc.).\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.MCARMechanism"},{"category":"type","location":"api/#MissingDataViz.MCARTests.MCARTestComparison","page":"API Reference","text":"MCARTestComparison\n\nStores results from multiple MCAR tests for comparison.\n\nFields\n\nlittle_result::Union{TestResult, Nothing}: Little's test result\nmeans_results::Dict{Symbol, TestResult}: Pairwise t-test results\nlogistic_results::Dict{Symbol, TestResult}: Logistic regression results\nsummary::String: Text summary of all results\nrecommendation::String: Recommended approach based on results\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.MCARTestComparison"},{"category":"function","location":"api/#MissingDataViz.MCARTests.generate_mcar_data","page":"API Reference","text":"generate_mcar_data(n_rows, n_cols, missing_rate; seed=42) -> DataFrame\n\nGenerate a dataset where missingness is MCAR: values are missing completely at random, independent of all variables.\n\nArguments\n\nn_rows::Int: Number of observations.\nn_cols::Int: Number of columns (all numeric, normally distributed).\nmissing_rate::Float64: Proportion of missing values per column (0.0–1.0).\nseed::Int: Random seed for reproducibility.\n\nReturns\n\nA DataFrame where each column independently has missing_rate fraction of values replaced by missing at random positions.\n\nGround truth\n\nTests on this data should NOT reject MCAR (H0 not rejected). Expected false positive rate ≤ alpha across many runs.\n\nExample\n\ndf = generate_mcar_data(200, 5, 0.20)\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.generate_mcar_data"},{"category":"function","location":"api/#MissingDataViz.MCARTests.generate_mar_data","page":"API Reference","text":"generate_mar_data(n_rows, n_cols, missing_rate; seed=42) -> DataFrame\n\nGenerate a dataset where missingness is MAR: values in column x2 are missing depending on the observed value of x1. High values of x1 increase the probability that x2 is missing.\n\nArguments\n\nn_rows::Int: Number of observations.\nn_cols::Int: Number of columns (minimum 2).\nmissing_rate::Float64: Average proportion of missing values in x2.\nseed::Int: Random seed for reproducibility.\n\nReturns\n\nA DataFrame where x2 has missing values that depend on x1 (MAR mechanism). x1 is always complete (it's the predictor). Other columns are MCAR with the same missing_rate.\n\nGround truth\n\nTests on x2 (using x1 as predictor) SHOULD reject MCAR. The dependence is deliberate and detectable.\n\nExample\n\ndf = generate_mar_data(200, 4, 0.20)\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.generate_mar_data"},{"category":"function","location":"api/#MissingDataViz.MCARTests.generate_mnar_data","page":"API Reference","text":"generate_mnar_data(n_rows, n_cols, missing_rate; seed=42) -> DataFrame\n\nGenerate a dataset where missingness is MNAR: values in x2 are missing depending on the (unobserved) value of x2 itself. High values of x2 are more likely to be missing.\n\nArguments\n\nn_rows::Int: Number of observations.\nn_cols::Int: Number of columns (minimum 2).\nmissing_rate::Float64: Average proportion of missing values in x2.\nseed::Int: Random seed for reproducibility.\n\nReturns\n\nA DataFrame where x2 has missing values that depend on x2's own value (MNAR mechanism). This is the hardest mechanism to detect.\n\nGround truth\n\nMNAR is theoretically undetectable from observed data alone. Tests may or may not reject MCAR depending on correlation structure. This generator is provided for stress-testing and documentation purposes.\n\nImportant limitation\n\nOur MCAR tests CANNOT reliably distinguish MNAR from MAR. A rejection of MCAR on MNAR data is possible but not guaranteed.\n\nExample\n\ndf = generate_mnar_data(200, 4, 0.20)\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.generate_mnar_data"},{"category":"function","location":"api/#MissingDataViz.MCARTests.describe_missing_mechanism","page":"API Reference","text":"describe_missing_mechanism(df) -> Nothing\n\nPrint a diagnostic summary of the missing data structure in a DataFrame. Used to verify synthetic datasets before running tests.\n\nExample\n\ndf = generate_mar_data(200, 4, 0.20)\ndescribe_missing_mechanism(df)\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.describe_missing_mechanism"},{"category":"type","location":"api/#MissingDataViz.MCARTests.ValidationMetrics","page":"API Reference","text":"ValidationMetrics\n\nStores validation results for a batch of MCAR test runs on synthetic datasets with known ground truth.\n\nFields\n\nn_runs::Int: Total number of test runs.\nn_correct::Int: Number of runs where test decision matched ground truth.\nn_false_positive::Int: MCAR rejected when data truly is MCAR.\nn_false_negative::Int: MCAR not rejected when data is MAR or MNAR.\ntrue_positive_rate::Float64: Sensitivity (correctly detected violations).\nfalse_positive_rate::Float64: Type I error rate (should be ≤ alpha).\nalpha::Float64: Significance threshold used.\n\nNotes\n\nFor MCAR data: correct decision = NOT rejected (true negative). For MAR/MNAR data: correct decision = rejected (true positive).\n\n\n\n\n\n","title":"MissingDataViz.MCARTests.ValidationMetrics"},{"category":"function","location":"api/#MissingDataViz.generate_html_report","page":"API Reference","text":"generate_html_report(df::DataFrame, output_file::String;\n                     title::String=\"Missing Data Analysis Report\",\n                     run_mcar_tests::Bool=false,\n                     alpha::Float64=0.05,\n                     mcar_results=nothing)\n\nGenerate a comprehensive HTML report with missing data analysis and visualizations.\n\nCreates a standalone HTML file containing:\n\nSummary statistics table (missing count and percentage per column)\nMissing data matrix heatmap\nBar chart of missing percentages\nCorrelation matrix of missingness patterns\nCombined overview dashboard\nOptional: MCAR diagnostic section with test results and recommendations\n\nAll plots are embedded as base64-encoded PNG images, making the report a single self-contained file with no external dependencies.\n\nArguments\n\ndf::DataFrame: Input data to analyze\noutput_file::String: Path where HTML report will be saved\nRelative paths are resolved from current working directory (pwd())\nAbsolute paths are used as-is\ntitle::String=\"Missing Data Analysis Report\": Report title displayed in header\nrun_mcar_tests::Bool=false: Whether to run MCAR tests and add diagnostic section\nfalse (default): Basic report only — faster, no statistical tests\ntrue: Full report with MCAR diagnostic section (adds a few seconds)\nalpha::Float64=0.05: Significance threshold for MCAR tests (only used if run_mcar_tests=true)\nmcar_results=nothing: Pre-computed MCAR results (MCARTestComparison) to inject directly.\nnothing (default): Results are computed internally when run_mcar_tests=true\nProvide a pre-computed value to avoid double execution when called from full_missing_diagnosis\nWhen provided, run_mcar_tests must also be true for the section to render\n\nReturns\n\nString: Absolute path to the generated HTML file\n\nOutput File Path Behavior\n\n# Relative path → saved in current directory\ngenerate_html_report(df, \"report.html\")\n# → Saved at: pwd()/report.html\n\n# Absolute path → saved at specified location\ngenerate_html_report(df, \"/home/user/reports/analysis.html\")\n# → Saved at: /home/user/reports/analysis.html\n\n# Check current directory\npwd()  # See where relative paths will be saved\n\nExamples\n\nusing DataFrames, MissingDataViz\n\n# Create sample data with missing values\ndf = DataFrame(\n    Age    = [25, missing, 30, missing, 35],\n    Income = [50000, 60000, missing, 70000, missing],\n    Score  = [85, 90, missing, missing, 95]\n)\n\n# Generate basic report (no MCAR tests)\npath = generate_html_report(df, \"missing_analysis.html\")\nprintln(\"Report saved to: $path\")\n\n# Generate full report with MCAR diagnostic section\npath = generate_html_report(df, \"full_report.html\",\n                             title=\"Q4 2024 Data Quality Report\",\n                             run_mcar_tests=true)\n\n# Generate report with custom significance threshold\npath = generate_html_report(df, \"strict_report.html\",\n                             run_mcar_tests=true,\n                             alpha=0.01)\n\n# Inject pre-computed results (avoids double execution)\nmcar = compare_mcar_tests(df)\npath = generate_html_report(df, \"fast_report.html\",\n                             run_mcar_tests=true,\n                             mcar_results=mcar)\n\n# Open in browser (cross-platform)\nif Sys.iswindows()\n    run(`cmd /c start $path`)\nelseif Sys.isapple()\n    run(`open $path`)\nelse\n    run(`xdg-open $path`)\nend\n\nPerformance\n\nBasic report (runmcartests=false):            150-300ms for datasets with <10,000 rows\nFull report  (runmcartests=true):             +2-10s depending on dataset size and column count\nFull report  (mcar_results pre-computed):       ~same as basic — no test re-execution\nReport file size: ~500KB - 2MB depending on data size\nMemory usage: ~50MB peak (temporary plot rendering)\n\nNote\n\nThis function generates all visualizations automatically. Plots are always embedded as base64 PNG images for maximum portability.\n\nSee Also\n\nfull_missing_diagnosis: All-in-one pipeline (recommended entry point)\ndiagnose_missing: Legacy all-in-one analysis workflow\nplot_missing_diagnosis: Interactive dashboard (Phase 1 + Phase 2)\nCairoMakie.save(): For exporting individual plots to PNG/PDF/SVG\n\nThrows\n\nErrorException: If output directory doesn't exist or is not writable\nArgumentError: If DataFrame is empty or has no columns\n\n\n\n\n\n","title":"MissingDataViz.generate_html_report"},{"category":"function","location":"api/#MissingDataViz.diagnose_missing","page":"API Reference","text":"diagnose_missing(df::DataFrame; \n                 report::Bool=false,\n                 output::String=\"missing_report.html\",\n                 display::Bool=!report,\n                 verbose::Bool=false)\n\nPerform comprehensive missing data analysis with automatic visualization and reporting.\n\nThis is the main entry point for missing data diagnosis. It provides two modes:\n\nInteractive mode (report=false): Display plots and return statistics\nBatch mode (report=true): Generate HTML report silently\n\nArguments\n\ndf::DataFrame: Input data to analyze\nreport::Bool=false: Generate HTML report (batch mode)\nfalse (default): Interactive mode - display plots in current environment\ntrue: Batch mode - generate HTML file silently\noutput::String=\"missing_report.html\": Output path for HTML report\nOnly used when report=true\nRelative paths resolved from pwd()\nAbsolute paths used as-is\ndisplay::Bool=!report: Display plots interactively\nIgnored if report=true (batch mode implies no interactive display)\nOnly effective in interactive mode (report=false)\nverbose::Bool=false: Enable detailed logging\nfalse (default): Minimal output - only final result message\ntrue: Detailed logging of each step\n\nReturns\n\nDict with the following structure:\nDict(\n    :stats => Dict(\n        :total_missing => Int,\n        :total_cells => Int,\n        :overall_percentage => Float64,\n        :columns => Dict(\"col\" => Dict(:count, :percentage))\n    ),\n    :figures => Dict(\n        :matrix => Figure,\n        :bars => Figure,\n        :correlation => Figure,\n        :overview => Figure\n    ),\n    :report_path => String  # Only present if report=true\n)\n\nBehavior\n\nInteractive Mode (report=false)\n\n# Display plots and return statistics\nresults = diagnose_missing(df)\n\n# Access statistics\nprintln(\"Total missing: \", results[:stats][:total_missing])\n\n# Access figures for further manipulation\nmatrix_fig = results[:figures][:matrix]\nsave(\"custom_matrix.png\", matrix_fig)  # Export with CairoMakie\n\n# Suppress display (compute only)\nresults = diagnose_missing(df, display=false)\n\nBatch Mode (report=true)\n\n# Generate HTML report silently\nresults = diagnose_missing(df, report=true)\nprintln(\"Report: \", results[:report_path])\n\n# Custom output path\nresults = diagnose_missing(df, report=true, output=\"analysis/report.html\")\n\n# Verbose logging\nresults = diagnose_missing(df, report=true, verbose=true)\n# → \"Computing missing data statistics...\"\n# → \"Generating visualizations...\"\n# → \"Generating HTML report...\"\n# → \"Report generated: /path/to/report.html\"\n\nExamples\n\nusing DataFrames, MissingDataViz\n\n# Create sample data\ndf = DataFrame(\n    Name = [\"Alice\", \"Bob\", missing, \"David\", \"Eve\"],\n    Age = [25, missing, 30, missing, 35],\n    Salary = [50000, 60000, missing, 70000, missing],\n    Department = [\"HR\", \"IT\", \"IT\", missing, \"HR\"]\n)\n\n# Example 1: Quick interactive analysis\nresults = diagnose_missing(df)\n# → Displays 4 plots automatically\n# → Returns statistics and figures\n\n# Example 2: Generate report for sharing\nresults = diagnose_missing(df, report=true, output=\"team_review.html\")\n# → Creates team_review.html\n# → Silent execution (no plots displayed)\n\n# Example 3: Debug mode with verbose logging\nresults = diagnose_missing(df, report=true, verbose=true)\n# → Shows detailed progress of each step\n\n# Example 4: Compute stats without displaying plots\nresults = diagnose_missing(df, display=false)\n# → No visual output, only statistics computed\n\n# Example 5: Access specific statistics\nresults = diagnose_missing(df)\nfor (col, stats) in results[:stats][:columns]\n    if stats[:percentage] > 20\n        println(\"$col has $(stats[:percentage])% missing - investigate!\")\n    end\nend\n\nPerformance\n\nInteractive mode: 150-250ms (display time depends on backend)\nBatch mode: 200-350ms (includes HTML generation and file write)\nMemory: ~50-100MB peak (temporary plot rendering)\n\nNotes\n\nThe display parameter is ignored when report=true to avoid confusion\nIn batch mode, plots are never displayed interactively\nAll plots are always generated (for both modes)\nUse verbose=true for debugging or progress monitoring\n\nSee Also\n\ngenerate_html_report: Generate HTML report only (no interactive display)\nplot_missing_overview: Generate combined overview plot only\nCairoMakie.save(): Export individual plots to files\n\nThrows\n\nArgumentError: If DataFrame is empty or has no columns\nErrorException: If report output directory doesn't exist (batch mode only)\n\n\n\n\n\ndiagnose_missing(df::DataFrame, output_file::String; kwargs...)\n\nConvenience method: Generate report by default when output file is specified.\n\nThis is a shorthand for diagnose_missing(df; report=true, output=output_file, kwargs...).\n\nExamples\n\n# These two calls are equivalent:\ndiagnose_missing(df, \"report.html\")\ndiagnose_missing(df, report=true, output=\"report.html\")\n\n\n\n\n\n","title":"MissingDataViz.diagnose_missing"},{"category":"function","location":"api/#MissingDataViz.full_missing_diagnosis","page":"API Reference","text":"full_missing_diagnosis(df::DataFrame;\n                       output::String          = \"missing_report.html\",\n                       title::String           = \"Missing Data Diagnosis\",\n                       run_mcar_tests::Bool    = true,\n                       alpha::Float64          = 0.05,\n                       export_dashboard::Bool  = true,\n                       dashboard_file::String  = \"missing_dashboard.png\",\n                       verbose::Bool           = false)\n\nRun the complete missing data diagnosis pipeline in a single call.\n\nExecutes all phases sequentially:\n\nInput validation — checks DataFrame integrity\nPattern detection — computes missing statistics per column\nVisualizations — generates all Phase 1 plots\nMCAR tests — runs Little's, t-tests, and logistic regression (optional)\nHTML report — assembles and saves a self-contained report\nDashboard export — saves the 2×2 diagnostic dashboard as PNG (optional)\n\nArguments\n\nRequired\n\ndf::DataFrame: Input dataset to analyze\n\nOutput control\n\noutput::String=\"missing_report.html\": Path for the HTML report\nRelative paths resolved from pwd()\nDirectory must exist\ntitle::String=\"Missing Data Diagnosis\": Report and dashboard title\nexport_dashboard::Bool=true: Whether to export the 2×2 dashboard PNG\ndashboard_file::String=\"missing_dashboard.png\": Path for dashboard PNG\n\nStatistical tests\n\nrun_mcar_tests::Bool=true: Whether to run MCAR statistical tests\nAdds ~2-10s depending on dataset size\nIncludes Little's test, Welch t-tests, logistic regression\nalpha::Float64=0.05: Significance threshold for all MCAR tests\n\nLogging\n\nverbose::Bool=false: Whether to print step-by-step progress logs\nfalse: Silent execution, only errors surfaced\ntrue: Detailed logs with timing for each step\n\nReturns\n\nDict{Symbol, Any} with keys:\n\nKey Type Description\n:report_path String Absolute path to HTML report\n:dashboard_path String or nothing Absolute path to dashboard PNG\n:stats Dict Missing statistics per column\n:mcar_results MCARTestComparison or nothing Full MCAR test results\n:n_violations Int Number of MCAR violations detected\n:violated_cols Vector{Symbol} Columns violating MCAR\n:recommendation String Top-level imputation recommendation\n:elapsed_seconds Float64 Total pipeline execution time\n\nExamples\n\nusing DataFrames, MissingDataViz\n\n# ── Minimal call (all defaults) ──────────────────────────────\ndf = generate_mar_data(300, 5, 0.20)\nresults = full_missing_diagnosis(df)\nprintln(\"Report: \", results[:report_path])\nprintln(\"Violations: \", results[:violated_cols])\n\n# ── Custom output paths ──────────────────────────────────────\nresults = full_missing_diagnosis(df,\n    output           = \"/reports/q4_analysis.html\",\n    dashboard_file   = \"/reports/q4_dashboard.png\",\n    title            = \"Q4 2025 Data Quality Report\")\n\n# ── Verbose mode for debugging ───────────────────────────────\nresults = full_missing_diagnosis(df, verbose=true)\n\n# ── Disable MCAR tests for fast turnaround ───────────────────\nresults = full_missing_diagnosis(df, run_mcar_tests=false)\n\n# ── Strict threshold ─────────────────────────────────────────\nresults = full_missing_diagnosis(df, alpha=0.01)\n\n# ── Access results programmatically ──────────────────────────\nresults = full_missing_diagnosis(df)\nif !isempty(results[:violated_cols])\n    println(\"⚠ Investigate: \", join(results[:violated_cols], \", \"))\nend\n\nPerformance\n\nWithout MCAR tests: ~300-500ms for datasets <10,000 rows\nWith MCAR tests:    +2-10s depending on column count and dataset size\n\nSee Also\n\ngenerate_html_report: Report only, no dashboard export\nplot_missing_diagnosis: Dashboard plot only\ncompare_mcar_tests: MCAR tests only\n\nThrows\n\nArgumentError: If DataFrame is empty or has no columns\nErrorException: If output directory does not exist\n\n\n\n\n\n","title":"MissingDataViz.full_missing_diagnosis"},{"category":"type","location":"api/#MissingDataViz.PatternInfo","page":"API Reference","text":"PatternInfo\n\nStructure to store information about a specific missing data pattern.\n\nFields\n\npattern::Vector{Bool}: The binary pattern (true = missing, false = present)\ncount::Int: Number of rows with this pattern\nfrequency::Float64: Percentage of rows with this pattern (0.0 to 100.0)\nrow_indices::Vector{Int}: Indices of rows that have this pattern\n\nExamples\n\ninfo = PatternInfo(\n    pattern = [true, false, true],\n    count = 5,\n    frequency = 25.0,\n    row_indices = [2, 7, 10, 15, 18]\n)\n\n\n\n\n\n","title":"MissingDataViz.PatternInfo"},{"category":"type","location":"api/#MissingDataViz.MissingDataVizError","page":"API Reference","text":"MissingDataVizError\n\nAbstract base type for all MissingDataViz-specific errors.\n\n\n\n\n\n","title":"MissingDataViz.MissingDataVizError"},{"category":"type","location":"api/#MissingDataViz.InvalidDataFrameError","page":"API Reference","text":"InvalidDataFrameError <: MissingDataVizError\n\nThrown when a DataFrame is invalid for processing.\n\nFields\n\nmessage::String: Description of the validation failure\nsuggestion::String: Actionable suggestion to fix the issue\n\n\n\n\n\n","title":"MissingDataViz.InvalidDataFrameError"},{"category":"type","location":"api/#MissingDataViz.InvalidParameterError","page":"API Reference","text":"InvalidParameterError <: MissingDataVizError\n\nThrown when a function parameter has an invalid value.\n\nFields\n\nparameter::String: Name of the invalid parameter\nvalue::Any: The invalid value provided\nconstraint::String: Description of valid values\n\n\n\n\n\n","title":"MissingDataViz.InvalidParameterError"},{"category":"type","location":"api/#MissingDataViz.InsufficientDataError","page":"API Reference","text":"InsufficientDataError <: MissingDataVizError\n\nThrown when a DataFrame doesn't have enough data for the requested operation.\n\nFields\n\noperation::String: The operation that requires more data\nrequired::String: Description of minimum requirements\nactual::String: Description of actual data available\n\n\n\n\n\n","title":"MissingDataViz.InsufficientDataError"},{"category":"function","location":"api/#MissingDataViz.validate_dataframe","page":"API Reference","text":"validate_dataframe(df)\n\nValidate that df is a valid DataFrame for processing.\n\nThrows\n\nArgumentError: If df is not a DataFrame\nInvalidDataFrameError: If DataFrame is empty or has no columns\n\nReturns\n\nNothing if validation passes.\n\n\n\n\n\n","title":"MissingDataViz.validate_dataframe"},{"category":"section","location":"getting-started/#Getting-Started","page":"Getting Started","text":"This guide will help you install MissingDataViz.jl and create your first visualization in under 5 minutes.\n\n","title":"Getting Started"},{"category":"section","location":"getting-started/#Installation","page":"Getting Started","text":"","title":"Installation"},{"category":"section","location":"getting-started/#Method-1:-From-Julia-General-Registry-(Recommended)","page":"Getting Started","text":"Once the package is registered (after v0.1.0 release):\n\nusing Pkg\nPkg.add(\"MissingDataViz\")","title":"Method 1: From Julia General Registry (Recommended)"},{"category":"section","location":"getting-started/#Method-2:-From-GitHub-(Current)","page":"Getting Started","text":"For the latest development version:\n\nusing Pkg\nPkg.add(url=\"https://github.com/DescarteS96/MissingDataViz.jl\")","title":"Method 2: From GitHub (Current)"},{"category":"section","location":"getting-started/#Method-3:-Local-Development","page":"Getting Started","text":"If you've cloned the repository:\n\nusing Pkg\nPkg.activate(\"/path/to/MissingDataViz\")\nPkg.instantiate()\n\n","title":"Method 3: Local Development"},{"category":"section","location":"getting-started/#Quick-Start:-Your-First-Plot-in-5-Minutes","page":"Getting Started","text":"","title":"Quick Start: Your First Plot in 5 Minutes"},{"category":"section","location":"getting-started/#Step-1:-Load-the-package","page":"Getting Started","text":"using MissingDataViz\nusing DataFrames","title":"Step 1: Load the package"},{"category":"section","location":"getting-started/#Step-2:-Create-sample-data-with-missing-values","page":"Getting Started","text":"# Create a DataFrame with some missing values\ndf = DataFrame(\n    PatientID = 1:10,\n    Age = [25, missing, 35, 42, missing, 28, 31, missing, 45, 38],\n    Weight = [70, 65, missing, 80, 75, missing, 68, 72, missing, 77],\n    BloodPressure = [120, 118, missing, 135, missing, 122, missing, 128, 140, 125],\n    Cholesterol = [missing, 180, 195, missing, 210, 185, missing, 200, 220, 190]\n)","title":"Step 2: Create sample data with missing values"},{"category":"section","location":"getting-started/#Step-3:-Generate-complete-analysis","page":"Getting Started","text":"# One-line complete diagnosis\nresults = diagnose_missing(df)\n\nWhat happens:\n\nFour plots are automatically displayed:\nMissing data matrix (heatmap showing pattern)\nBar chart (percentage missing per column)\nCorrelation matrix (which columns tend to be missing together)\nOverview dashboard (all three combined)","title":"Step 3: Generate complete analysis"},{"category":"section","location":"getting-started/#Step-4:-Access-statistics","page":"Getting Started","text":"# Get detailed statistics\nstats = results[:stats]\n\nprintln(\"Total missing values: \", stats[:total_missing])\nprintln(\"Overall percentage: \", stats[:overall_percentage], \"%\")\n\n# Per-column breakdown\nfor (col, info) in stats[:columns]\n    println(\"$col: $(info[:percentage])% missing ($(info[:count]) values)\")\nend\n\nOutput:\n\nTotal missing values: 13\nOverall percentage: 32.5%\nPatientID: 0.0% missing (0 values)\nAge: 30.0% missing (3 values)\nWeight: 30.0% missing (3 values)\nBloodPressure: 30.0% missing (3 values)\nCholesterol: 40.0% missing (4 values)\n\n","title":"Step 4: Access statistics"},{"category":"section","location":"getting-started/#Save-Your-Work","page":"Getting Started","text":"","title":"Save Your Work"},{"category":"section","location":"getting-started/#Export-individual-plots","page":"Getting Started","text":"using CairoMakie\n\n# Save the matrix plot\nsave(\"missing_matrix.png\", results[:figures][:matrix])\n\n# Save the overview dashboard\nsave(\"overview.pdf\", results[:figures][:overview])","title":"Export individual plots"},{"category":"section","location":"getting-started/#Generate-HTML-report","page":"Getting Started","text":"# Create standalone HTML report\ndiagnose_missing(df, report=true, output=\"analysis_report.html\")\n\n# Open it in your browser manually, or:\n# Windows: run(`cmd /c start analysis_report.html`)\n# macOS: run(`open analysis_report.html`)\n# Linux: run(`xdg-open analysis_report.html`)\n\n","title":"Generate HTML report"},{"category":"section","location":"getting-started/#Next-Steps","page":"Getting Started","text":"","title":"Next Steps"},{"category":"section","location":"getting-started/#Explore-Individual-Visualizations","page":"Getting Started","text":"Instead of diagnose_missing(), you can create plots individually:\n\n# Just the matrix heatmap\nfig1 = plot_missing_matrix(df)\n\n# Just the bar chart\nfig2 = plot_missing_bars(df)\n\n# Just the correlation matrix\nfig3 = plot_missing_correlation(df)\n\n# Combined overview\nfig4 = plot_missing_overview(df)","title":"Explore Individual Visualizations"},{"category":"section","location":"getting-started/#Customize-Your-Plots","page":"Getting Started","text":"All plotting functions accept customization options:\n\n# Custom size and threshold\nplot_missing_bars(df, \n    figsize=(1000, 700),\n    threshold=25.0  # Show line at 25% missing\n)\n\n# Horizontal orientation for many columns\nplot_missing_bars(df, orientation=:horizontal)\n\n# Hide sparkline in matrix plot\nplot_missing_matrix(df, show_sparkline=false)","title":"Customize Your Plots"},{"category":"section","location":"getting-started/#Pattern-Detection","page":"Getting Started","text":"Get detailed pattern analysis:\n\n# Summary of all missing data patterns\nsummary = summarize_missing(df)\n\nprintln(\"Total cells: \", summary.total_cells)\nprintln(\"Missing cells: \", summary.n_missing)\nprintln(\"Top 5 patterns:\")\nfor (pattern, count) in summary.top_patterns\n    println(\"  Pattern: \", pattern, \" → \", count, \" rows\")\nend\n\n","title":"Pattern Detection"},{"category":"section","location":"getting-started/#Common-Use-Cases","page":"Getting Started","text":"","title":"Common Use Cases"},{"category":"section","location":"getting-started/#1.-Quick-Data-Quality-Check","page":"Getting Started","text":"# Load your data\ndf = CSV.read(\"mydata.csv\", DataFrame)\n\n# Instant visual diagnosis\ndiagnose_missing(df)","title":"1. Quick Data Quality Check"},{"category":"section","location":"getting-started/#2.-Pre-Processing-for-Machine-Learning","page":"Getting Started","text":"# Check missing data before training\nresults = diagnose_missing(df, display=false)\n\n# Identify problematic columns\nhigh_missing = [\n    col for (col, stats) in results[:stats][:columns]\n    if stats[:percentage] > 30.0\n]\n\nprintln(\"Consider removing or imputing: \", high_missing)","title":"2. Pre-Processing for Machine Learning"},{"category":"section","location":"getting-started/#3.-Generate-Report-for-Stakeholders","page":"Getting Started","text":"# Create professional HTML report\ndiagnose_missing(df, \n    report=true, \n    output=\"data_quality_report_$(Dates.today()).html\"\n)\n\n","title":"3. Generate Report for Stakeholders"},{"category":"section","location":"getting-started/#Troubleshooting","page":"Getting Started","text":"","title":"Troubleshooting"},{"category":"section","location":"getting-started/#Plots-not-displaying","page":"Getting Started","text":"If plots don't appear automatically:\n\nusing CairoMakie\nCairoMakie.activate!()\n\nresults = diagnose_missing(df)","title":"Plots not displaying"},{"category":"section","location":"getting-started/#Out-of-memory-with-large-datasets","page":"Getting Started","text":"For very large datasets (>100k rows):\n\n# Compute statistics without rendering plots\nresults = diagnose_missing(df, display=false)\n\n# Access stats without creating figures\nprintln(results[:stats])","title":"Out of memory with large datasets"},{"category":"section","location":"getting-started/#File-path-issues-on-Windows","page":"Getting Started","text":"Use double backslashes or raw strings:\n\n# Method 1: Double backslashes\ndiagnose_missing(df, report=true, output=\"C:\\\\Users\\\\Name\\\\report.html\")\n\n# Method 2: Raw string\ndiagnose_missing(df, report=true, output=raw\"C:\\Users\\Name\\report.html\")\n\n# Method 3: Forward slashes (works on Windows too)\ndiagnose_missing(df, report=true, output=\"C:/Users/Name/report.html\")\n\n","title":"File path issues on Windows"},{"category":"section","location":"getting-started/#What-You've-Learned","page":"Getting Started","text":"✅ Install MissingDataViz.jl   ✅ Create basic visualizations with one line of code   ✅ Access detailed statistics programmatically   ✅ Export plots and generate reports   ✅ Customize visualizations for your needs  \n\n","title":"What You've Learned"},{"category":"section","location":"getting-started/#Where-to-Go-Next","page":"Getting Started","text":"API Reference: Complete function documentation\nUser Guide: Advanced workflows and batch processing\nExamples: Real-world use cases\n\n","title":"Where to Go Next"},{"category":"section","location":"getting-started/#Need-Help?","page":"Getting Started","text":"📖 Full Documentation\n🐛 Report a Bug\n💬 Ask a Question","title":"Need Help?"},{"category":"section","location":"#MissingDataViz.jl","page":"Home","text":"Professional missing data visualization and diagnosis for Julia DataFrames\n\n","title":"MissingDataViz.jl"},{"category":"section","location":"#Overview","page":"Home","text":"MissingDataViz.jl provides comprehensive tools for analyzing and visualizing missing data patterns in tabular datasets. It combines intuitive visualizations with robust pattern detection to help you understand the structure of missingness in your data.\n\nKey Features:\n\n🔍 Pattern Detection: Identify unique missing data patterns and their frequencies\n📊 Multiple Visualizations: Matrix heatmaps, bar charts, correlation matrices, overview dashboards\n📄 HTML Reports: Generate standalone reports with embedded visualizations\n💾 Export Flexibility: Save plots as PNG, PDF, or SVG\n⚡ One-Line Diagnosis: Complete analysis with diagnose_missing()\n\n","title":"Overview"},{"category":"section","location":"#Installation","page":"Home","text":"using Pkg\nPkg.add(\"MissingDataViz\")\n\nDevelopment version:\n\nusing Pkg\nPkg.add(url=\"https://github.com/DescarteS96/MissingDataViz.jl\")\n\n","title":"Installation"},{"category":"section","location":"#Quick-Start","page":"Home","text":"using MissingDataViz\nusing DataFrames\n\n# Create sample data with missing values\ndf = DataFrame(\n    Name = [\"Alice\", \"Bob\", missing, \"David\", \"Eve\"],\n    Age = [25, missing, 30, missing, 35],\n    Salary = [50000, 60000, missing, 70000, missing],\n    Department = [\"HR\", \"IT\", \"IT\", missing, \"HR\"]\n)\n\n# One-line complete analysis\nresults = diagnose_missing(df)\n# → Displays 4 plots automatically\n# → Returns statistics and figures\n\n# Generate HTML report for sharing\ndiagnose_missing(df, report=true, output=\"analysis.html\")\n# → Creates standalone HTML file\n\n","title":"Quick Start"},{"category":"section","location":"#Visualizations","page":"Home","text":"","title":"Visualizations"},{"category":"section","location":"#Missing-Data-Matrix","page":"Home","text":"fig = plot_missing_matrix(df)\n\nShows: Binary heatmap of missing values (black = missing, white = present) with optional sparkline showing % missing per row.","title":"Missing Data Matrix"},{"category":"section","location":"#Bar-Chart","page":"Home","text":"fig = plot_missing_bars(df)\n\nShows: Percentage of missing values per column, color-coded by severity (blue < 20%, orange 20-50%, red ≥ 50%).","title":"Bar Chart"},{"category":"section","location":"#Correlation-Matrix","page":"Home","text":"fig = plot_missing_correlation(df)\n\nShows: Correlation between missing data patterns across columns to detect co-occurrence.","title":"Correlation Matrix"},{"category":"section","location":"#Overview-Dashboard","page":"Home","text":"fig = plot_missing_overview(df)\n\nShows: Combined view of all three plots above in a single figure.\n\n","title":"Overview Dashboard"},{"category":"section","location":"#Workflows","page":"Home","text":"","title":"Workflows"},{"category":"section","location":"#Interactive-Analysis","page":"Home","text":"# Display plots and access statistics\nresults = diagnose_missing(df)\n\n# Access statistics\nprintln(\"Total missing: \", results[:stats][:total_missing])\nprintln(\"Overall %: \", results[:stats][:overall_percentage])\n\n# Save individual plots\nusing CairoMakie\nsave(\"matrix.png\", results[:figures][:matrix])\nsave(\"overview.pdf\", results[:figures][:overview])","title":"Interactive Analysis"},{"category":"section","location":"#Batch-Reporting","page":"Home","text":"# Generate HTML report (no interactive display)\nresults = diagnose_missing(df, report=true, output=\"report.html\")\n\n# Open in browser\npath = results[:report_path]\n# Windows: run(`cmd /c start $path`)\n# macOS: run(`open $path`)\n# Linux: run(`xdg-open $path`)\n\n","title":"Batch Reporting"},{"category":"section","location":"#Navigation","page":"Home","text":"Pages = [\"api.md\", \"guide.md\"]\nDepth = 2\n\nAPI Reference: Complete function documentation\nUser Guide: Detailed workflows, troubleshooting, and examples\n\n","title":"Navigation"},{"category":"section","location":"#Performance","page":"Home","text":"Interactive mode: 150-250ms for typical datasets (1000 rows × 10 columns)\nBatch mode: 200-350ms (includes HTML generation)\nMaximum recommended size: 100k rows × 100 columns\n\n","title":"Performance"},{"category":"section","location":"#Support","page":"Home","text":"GitHub: github.com/DescarteS96/MissingDataViz.jl\nIssues: Report bugs or request features\nDocumentation: Online docs\n\n","title":"Support"},{"category":"section","location":"#Citation","page":"Home","text":"If you use MissingDataViz.jl in your research, please cite:\n\n@software{missingdataviz2026,\n  author = {Ballamou, Rene Fassou and Yenilmez, Ismail},\n  title  = {MissingDataViz.jl: Missing Data Visualization for Julia},\n  year   = {2026},\n  url    = {https://github.com/DescarteS96/MissingDataViz.jl}\n}\n\n","title":"Citation"},{"category":"section","location":"#Index","page":"Home","text":"","title":"Index"}]
}
